-- Oracle EBS R12 -> canonical INVOICE_LINE (ORACLE_EBS). Generated by tools/build_silver_sql.py.
SELECT 'ORACLE_EBS' AS SOURCE_SLOT, 'Oracle EBS R12' AS SOURCE_SYSTEM, 'ORACLE_EBS' AS COMPANY_CODE, i.INVOICE_NUM AS INVOICE_ID, h.SEGMENT1 AS PO_NUMBER, pl.LINE_NUM::STRING AS PO_ITEM,
  i.VENDOR_ID::STRING AS SUPPLIER_ID, i.INVOICE_DATE, il.QUANTITY_INVOICED AS INV_QTY, il.AMOUNT AS INV_AMOUNT, i.INVOICE_CURRENCY_CODE AS CURRENCY
FROM {{ source('src_oracle_ebs', 'ap_invoice_lines_all') }} il JOIN {{ source('src_oracle_ebs', 'ap_invoices_all') }} i ON i.INVOICE_ID = il.INVOICE_ID
LEFT JOIN {{ source('src_oracle_ebs', 'po_lines_all') }} pl ON pl.PO_LINE_ID = il.PO_LINE_ID LEFT JOIN {{ source('src_oracle_ebs', 'po_headers_all') }} h ON h.PO_HEADER_ID = il.PO_HEADER_ID
